from z3 import *

def main():
    houses = [1, 2]
    names = ["Eric", "Arnold"]
    children = ["Bella", "Fred"]
    animals = ["cat", "horse"]
    mothers = ["Aniya", "Holly"]

    s = Solver()

    name_pos = {v: IntVar(f"name_pos_{v}") for v in names}
    child_pos = {v: IntVar(f"child_pos_{v}") for v in children}
    animal_pos = {v: IntVar(f"animal_pos_{v}") for v in animals}
    mother_pos = {v: IntVar(f"mother_pos_{v}") for v in mothers}

    for v in names:
        s.add(And(name_pos[v] >= 1, name_pos[v] <= 2))
    for v in children:
        s.add(And(child_pos[v] >= 1, child_pos[v] <= 2))
    for v in animals:
        s.add(And(animal_pos[v] >= 1, animal_pos[v] <= 2))
    for v in mothers:
        s.add(And(mother_pos[v] >= 1, mother_pos[v] <= 2))

    s.add(Distinct(*[name_pos[v] for v in names]))
    s.add(Distinct(*[child_pos[v] for v in children]))
    s.add(Distinct(*[animal_pos[v] for v in animals]))
    s.add(Distinct(*[mother_pos[v] for v in mothers]))

    s.add(mother_pos["Holly"] == child_pos["Bella"])
    s.add(name_pos["Arnold"] != 1)
    s.add(mother_pos["Holly"] > animal_pos["horse"])

    if s.check() != sat:
        return

    m = s.model()

    def value_at(pos_dict, house):
        for v, p in pos_dict.items():
            if m[p].as_long() == house:
                return v
        return "Unknown"

    for h in houses:
        print(f"House {h}: {value_at(name_pos, h)}, {value_at(child_pos, h)}, {value_at(animal_pos, h)}, {value_at(mother_pos, h)}")

if __name__ == "__main__":
    main()
```

